## Code Example
```javascript
function assignTenantResources(ckne, baseRefreshMs=10000, maxExtra=4000) {
  // Higher CKNE means more frequent refresh and cache priority
  const cadence = baseRefreshMs * (1 - ckne) + Math.min(ckne * maxExtra, maxExtra);
  const weight = 0.5 + ckne * 0.5; // routing weight between 0.5 and 1.0
  const cacheSlots = Math.max(1, Math.round(ckne * 10));
  return { cadence, weight, cacheSlots };
}
```

